		return s;

	return kstrdup(s, gfp);
}

char *kstrndup(const char *s, size_t max, gfp_t gfp)
{
	return s ? __kmemdup_nul(s, strnlen(s, max), gfp) : NULL;
}

void *kmemdup_noprof(const void *src, size_t len, gfp_t gfp)
{
