	if (!strcmp(arg, "off"))
		kasan_flag_write_only = false;
	else if (!strcmp(arg, "on"))
		kasan_flag_write_only = true;
	else
		return -EINVAL;

	return 0;
}

static inline const char *kasan_mode_info(void)
{
	if (kasan_mode == KASAN_MODE_ASYNC)
		return "async";
	else if (kasan_mode == KASAN_MODE_ASYMM)
		return "asymm";
