static struct inode *shmem_get_inode(struct mnt_idmap *idmap,
				     struct super_block *sb, struct inode *dir,
				     umode_t mode, dev_t dev, vma_flags_t flags)
{
	int err;
	struct inode *inode;

	inode = __shmem_get_inode(idmap, sb, dir, mode, dev, flags);
	if (IS_ERR(inode))
		return inode;

	err = dquot_initialize(inode);
	if (err)
		goto errout;

	err = dquot_alloc_inode(inode);
	if (err) {
		dquot_drop(inode);
		goto errout;
	}
	return inode;

errout:
	inode->i_flags |= S_NOQUOTA;
	iput(inode);
	return ERR_PTR(err);
}

static struct inode *shmem_get_inode(struct mnt_idmap *idmap,
				     struct super_block *sb, struct inode *dir,
				     umode_t mode, dev_t dev, vma_flags_t flags)
{
	return __shmem_get_inode(idmap, sb, dir, mode, dev, flags);
}

static struct folio *shmem_mfill_folio_alloc(struct vm_area_struct *vma,
					     unsigned long addr)
{
	struct inode *inode = file_inode(vma->vm_file);
	struct address_space *mapping = inode->i_mapping;
	struct shmem_inode_info *info = SHMEM_I(inode);
	pgoff_t pgoff = linear_page_index(vma, addr);
	gfp_t gfp = mapping_gfp_mask(mapping);
	struct folio *folio;

	if (unlikely(pgoff >= DIV_ROUND_UP(i_size_read(inode), PAGE_SIZE)))
		return NULL;

	folio = shmem_alloc_folio(gfp, 0, info, pgoff);
	if (!folio)
		return NULL;

	if (mem_cgroup_charge(folio, vma->vm_mm, GFP_KERNEL)) {
		folio_put(folio);
		return NULL;
	}

	return folio;
}

static int shmem_mfill_filemap_add(struct folio *folio,
				   struct vm_area_struct *vma,
				   unsigned long addr)
{
	struct inode *inode = file_inode(vma->vm_file);
	struct address_space *mapping = inode->i_mapping;
	pgoff_t pgoff = linear_page_index(vma, addr);
	gfp_t gfp = mapping_gfp_mask(mapping);
	int err;

	__folio_set_locked(folio);
	__folio_set_swapbacked(folio);

	err = shmem_add_to_page_cache(folio, mapping, pgoff, NULL, gfp);
	if (err)
		goto err_unlock;

	if (shmem_inode_acct_blocks(inode, 1)) {
		err = -ENOMEM;
		goto err_delete_from_cache;
	}

	folio_add_lru(folio);
	shmem_recalc_inode(inode, 1, 0);

	return 0;

err_delete_from_cache:
	filemap_remove_folio(folio);
err_unlock:
	folio_unlock(folio);
	return err;
}

static void shmem_mfill_filemap_remove(struct folio *folio,
				       struct vm_area_struct *vma)
{
	struct inode *inode = file_inode(vma->vm_file);

	filemap_remove_folio(folio);
	shmem_recalc_inode(inode, 0, 0);
	folio_unlock(folio);
}

static struct folio *shmem_get_folio_noalloc(struct inode *inode, pgoff_t pgoff)
{
	struct folio *folio;
	int err;

	err = shmem_get_folio(inode, pgoff, 0, &folio, SGP_NOALLOC);
	if (err)
		return ERR_PTR(err);

	return folio;
}

